//! gRPC client bridge used by the TUI.
//!
//! Wraps the `tonic` clients generated by `rt-grpc` for `TorrentService`,
//! `SystemService` and `CommandService` behind one type with a bounded timeout
//! per call. Every fallible path returns [`BridgeError`]; nothing in here
//! panics on transport or server failures.

use std::future::Future;
use std::time::Duration;

use rt_grpc::command_service_client::CommandServiceClient;
use rt_grpc::system_service_client::SystemServiceClient;
use rt_grpc::torrent_service_client::TorrentServiceClient;
use rt_grpc::{
    object_value, CommandRequest, CommandResponse, ControlTorrentRequest, Empty, GetTorrentRequest,
    ListTorrentsRequest, ObjectValue, RemoveTorrentRequest, SessionStatsResponse,
    SetTorrentPriorityRequest, TorrentAction as ProtoAction, TorrentDetails, TorrentSummary,
    VersionResponse,
};

use crate::actions::TorrentAction;
use tonic::transport::{Channel, Endpoint as TransportEndpoint};
use tonic::{Response, Status};

/// Timeout applied to bridge calls when the caller does not override it.
pub const DEFAULT_RPC_TIMEOUT: Duration = Duration::from_secs(5);

/// Client for the `rstorrent` gRPC daemon.
pub struct GrpcBridge {
    torrents: TorrentServiceClient<Channel>,
    system: SystemServiceClient<Channel>,
    commands: CommandServiceClient<Channel>,
    timeout: Duration,
}

impl GrpcBridge {
    /// Connects to `endpoint` and returns a ready-to-use bridge.
    ///
    /// Accepts `host:port`, `tcp://host:port`, `http://host:port` and
    /// `unix:///path/to.sock`. Both the connection attempt and every subsequent
    /// call are bounded by `timeout`.
    pub async fn connect(endpoint: &str, timeout: Duration) -> Result<Self, BridgeError> {
        let channel = connect_channel(endpoint, timeout).await?;

        Ok(Self {
            torrents: TorrentServiceClient::new(channel.clone()),
            system: SystemServiceClient::new(channel.clone()),
            commands: CommandServiceClient::new(channel),
            timeout,
        })
    }

    /// Lists torrents in `view` (`main`, `started`, `stopped`, …).
    pub async fn list_torrents(&mut self, view: &str) -> Result<Vec<TorrentSummary>, BridgeError> {
        let request = ListTorrentsRequest {
            view: view.to_string(),
            hashes: Vec::new(),
        };
        let response = await_response(self.timeout, self.torrents.list_torrents(request)).await?;

        Ok(response.torrents)
    }

    /// Fetches the details of a single torrent.
    pub async fn get_torrent(&mut self, hash: &str) -> Result<TorrentDetails, BridgeError> {
        let request = GetTorrentRequest {
            hash: hash.to_string(),
        };
        let details = await_response(self.timeout, self.torrents.get_torrent(request)).await?;

        if details.summary.is_none() {
            return Err(BridgeError::InvalidResponse(format!(
                "torrent `{hash}` was returned without a summary"
            )));
        }

        Ok(details)
    }

    /// Reads the daemon version banner.
    pub async fn version(&mut self) -> Result<VersionResponse, BridgeError> {
        let response = await_response(self.timeout, self.system.get_version(Empty {})).await?;

        if response.version.is_empty() {
            return Err(BridgeError::InvalidResponse(
                "daemon reported an empty version string".to_string(),
            ));
        }

        Ok(response)
    }

    /// Starts, stops, closes or re-checks a torrent.
    pub async fn control_torrent(
        &mut self,
        hash: &str,
        action: TorrentAction,
    ) -> Result<(), BridgeError> {
        let request = ControlTorrentRequest {
            hash: hash.to_string(),
            action: proto_action(action) as i32,
        };
        let response = await_response(self.timeout, self.torrents.control_torrent(request)).await?;

        ensure_success(response.success, "control")
    }

    /// Removes a torrent from the session, keeping its data on disk.
    pub async fn remove_torrent(&mut self, hash: &str) -> Result<(), BridgeError> {
        let request = RemoveTorrentRequest {
            hash: hash.to_string(),
            delete_data: false,
        };
        let response = await_response(self.timeout, self.torrents.remove_torrent(request)).await?;

        ensure_success(response.success, "remove")
    }

    /// Sets a torrent's priority (`0` off … `3` high).
    pub async fn set_torrent_priority(
        &mut self,
        hash: &str,
        priority: u32,
    ) -> Result<(), BridgeError> {
        let request = SetTorrentPriorityRequest {
            hash: hash.to_string(),
            priority,
        };
        let response =
            await_response(self.timeout, self.torrents.set_torrent_priority(request)).await?;

        ensure_success(response.success, "set priority")
    }

    /// Runs a command with integer arguments.
    pub async fn execute_ints(
        &mut self,
        command: &str,
        args: &[i64],
        target: Option<&str>,
    ) -> Result<CommandResponse, BridgeError> {
        let args = args
            .iter()
            .map(|value| ObjectValue {
                kind: Some(object_value::Kind::IntValue(*value)),
            })
            .collect();

        self.execute(command, args, target).await
    }

    /// Runs a command with string arguments (used by the load prompt).
    pub async fn execute_strings(
        &mut self,
        command: &str,
        args: &[String],
        target: Option<&str>,
    ) -> Result<CommandResponse, BridgeError> {
        let args = args
            .iter()
            .map(|value| ObjectValue {
                kind: Some(object_value::Kind::StringValue(value.clone())),
            })
            .collect();

        self.execute(command, args, target).await
    }

    /// Reads session-wide transfer statistics.
    pub async fn session_stats(&mut self) -> Result<SessionStatsResponse, BridgeError> {
        await_response(self.timeout, self.system.get_session_stats(Empty {})).await
    }

    /// Executes a command, optionally scoped to one torrent.
    pub async fn execute(
        &mut self,
        command: &str,
        args: Vec<ObjectValue>,
        target: Option<&str>,
    ) -> Result<CommandResponse, BridgeError> {
        let request = CommandRequest {
            command: command.to_string(),
            args,
            target_hash: target.unwrap_or_default().to_string(),
            trusted: false,
        };

        await_response(self.timeout, self.commands.execute(request)).await
    }
}

/// Resolves the user-supplied endpoint spelling into a tonic transport URI.
///
/// `BridgeError` has exactly four variants (TASK-02 contract), so an
/// unresolvable endpoint is reported as a connection-level failure.
fn transport_uri(raw: &str) -> Result<String, BridgeError> {
    let value = raw.trim();
    let unusable = |reason: &str| BridgeError::ConnectionLost(format!("`{raw}`: {reason}"));

    if value.is_empty() {
        return Err(unusable("endpoint is empty"));
    }

    if let Some(path) = value.strip_prefix("unix://") {
        if path.is_empty() {
            return Err(unusable("unix socket path is empty"));
        }
        // `tonic` understands the `unix:` scheme natively.
        return Ok(value.to_string());
    }

    if let Some(rest) = value.strip_prefix("tcp://") {
        return Ok(format!("http://{rest}"));
    }

    if value.starts_with("http://") || value.starts_with("https://") {
        return Ok(value.to_string());
    }

    Ok(format!("http://{value}"))
}

/// Builds a channel for `endpoint`, bounded by `timeout`.
async fn connect_channel(endpoint: &str, timeout: Duration) -> Result<Channel, BridgeError> {
    let uri = transport_uri(endpoint)?;
    let transport = TransportEndpoint::from_shared(uri)
        .map_err(|error| BridgeError::ConnectionLost(format!("`{endpoint}`: {error}")))?;

    match tokio::time::timeout(timeout, transport.connect()).await {
        Ok(Ok(channel)) => Ok(channel),
        Ok(Err(error)) => Err(BridgeError::ConnectionLost(format!(
            "`{endpoint}`: {error}"
        ))),
        Err(_elapsed) => Err(BridgeError::Timeout(timeout)),
    }
}

/// Applies the timeout to one RPC and unwraps its response body.
async fn await_response<T>(
    timeout: Duration,
    call: impl Future<Output = Result<Response<T>, Status>>,
) -> Result<T, BridgeError> {
    match tokio::time::timeout(timeout, call).await {
        Ok(Ok(response)) => Ok(response.into_inner()),
        Ok(Err(status)) => Err(BridgeError::ServerError {
            code: status.code(),
            message: status.message().to_string(),
        }),
        Err(_elapsed) => Err(BridgeError::Timeout(timeout)),
    }
}

/// Everything that can go wrong while talking to the daemon.
#[derive(Debug, thiserror::Error)]
pub enum BridgeError {
    /// The channel could not be established or was dropped.
    #[error("connection lost: {0}")]
    ConnectionLost(String),
    /// The call did not complete within the configured timeout.
    #[error("rpc timed out after {0:?}")]
    Timeout(Duration),
    /// The daemon answered with a gRPC error status.
    #[error("daemon returned {code}: {message}")]
    ServerError {
        /// gRPC status code returned by the daemon.
        code: tonic::Code,
        /// Human-readable status message.
        message: String,
    },
    /// The daemon answered successfully but with a payload the client rejects.
    #[error("invalid response: {0}")]
    InvalidResponse(String),
}

/// Maps the client action onto the proto enum.
fn proto_action(action: TorrentAction) -> ProtoAction {
    match action {
        TorrentAction::Start => ProtoAction::Start,
        TorrentAction::Stop => ProtoAction::Stop,
        TorrentAction::Close => ProtoAction::Close,
        TorrentAction::CheckHash => ProtoAction::CheckHash,
    }
}

/// Turns a `success: false` response into a typed error.
fn ensure_success(success: bool, operation: &str) -> Result<(), BridgeError> {
    if success {
        Ok(())
    } else {
        Err(BridgeError::InvalidResponse(format!(
            "daemon rejected `{operation}`"
        )))
    }
}
